import { Component, Element, Event, EventEmitter, Host, Prop, Watch, h } from '@stencil/core';
import { CLOSE_BUTTON_LABEL } from '../../a11y';
import { ToastNotificationSeverity } from '../../types';
import { handleAutofocus } from '../../utils/autofocus';

@Component({
  tag: 'groupui-toast',
  styleUrl: 'toast.scss',
  shadow: true,
})
export class Toast {
  /**
   * Severity of the toast notification
   */
  @Prop({ reflect: true }) readonly severity: ToastNotificationSeverity = 'none';

  /**
   * Hides Toast Notification after the given amount of milliseconds. Emits groupuiClose event.
   */
  @Prop({ reflect: true }) readonly autoDismiss: number;

  /**
   * Hides the close button that dismisses the toast
   */
  @Prop({ reflect: true }) readonly hideCloseButton: boolean = false;

  /**
   * Determines if the toast notification is visible or not.
   */
  @Prop({ reflect: true, mutable: true }) visible: boolean = false;

  /**
   * Defines the layout of the toast. When 'multiple' the action slot is always displayed under the message.
   */
  @Prop({ reflect: true }) readonly lines: 'single' | 'multiple' = 'single';

  /**
   * sets a custom accessible text for the close button
   */
  @Prop({ reflect: true, attribute: 'a11y-label-close-button' }) readonly a11yLabelCloseButton: string;

  /**
   * sets a custom accessible text for the severity icon (by default, it is hidden)
   */
  @Prop({ reflect: true, attribute: 'a11y-label-severity-icon' }) readonly a11yLabelSeverityIcon: string;

  @Element() host: HTMLElement;

  /**
   * Is dispatched when the toast notification is closed through click and/or autoDismiss.
   */
  @Event({ bubbles: false }) groupuiClose: EventEmitter<void>;
  /**
   * Dispatched when component finished loading
   */
  @Event({ bubbles: false }) groupuiDidLoad: EventEmitter<void>;

  private timeoutId: ReturnType<typeof setTimeout>;

  componentDidLoad() {
    this.groupuiDidLoad.emit();
    if (this.autoDismiss) {
      this.timeoutId = setTimeout(() => (this.visible = false), this.autoDismiss);
    }
    handleAutofocus(this.host);
  }

  @Watch('visible')
  onVisibleChange() {
    if (!this.visible) {
      this.groupuiClose.emit();
    }
    if (this.visible) {
      this.host.style.display = 'grid';
    }
    this.host.style.setProperty('--animation-duration', 'var(--groupui-sys-duration-medium-2)');
  }

  @Watch('autoDismiss')
  onAutoDismissChange() {
    if (this.autoDismiss) {
      clearTimeout(this.timeoutId);
      this.timeoutId = setTimeout(() => (this.visible = false), this.autoDismiss);
    }
  }

  private handleAnimationEnd = () => {
    if (!this.visible) {
      this.host.style.display = 'none';
    }
  };

  private handleCloseButtonClick = () => {
    this.visible = false;
    clearTimeout(this.timeoutId);
    this.timeoutId = undefined;
  };

  private getIconForSeverity(): string {
    switch (this.severity) {
      case 'information':
        return 'info-filled-24';
      case 'success':
        return 'success-filled-24';
      case 'warning':
        return 'warning-filled-24';
      case 'danger':
        return 'danger-filled-24';
      default:
        return 'info-filled-24';
    }
  }

  private isMessageSlotProvided(): boolean {
    return !!this.host.querySelector('[slot="message"]');
  }

  private isActionSlotProvided(): boolean {
    return !!this.host.querySelector('[slot="action"]');
  }

  render() {
    let ariaProps: { 'aria-label'?: string; 'aria-hidden'?: string };
    if (this.a11yLabelSeverityIcon) {
      ariaProps = { 'aria-label': this.a11yLabelSeverityIcon };
    } else {
      ariaProps = { 'aria-hidden': 'true' };
    }

    return (
      <Host
        onAnimationEnd={this.handleAnimationEnd}
        role="alert"
        class={{
          'has-message': this.isMessageSlotProvided(),
          'has-action': this.isActionSlotProvided(),
          'has-close': !this.hideCloseButton,
          'has-status': this.severity !== 'none',
          'multiple-lines': this.lines === 'multiple',
        }}
      >
        {this.severity !== 'none' && (
          <groupui-icon class="status-icon" name={this.getIconForSeverity()} {...ariaProps}></groupui-icon>
        )}
        <slot name="message"></slot>
        <slot name="action"></slot>
        {!this.hideCloseButton && (
          <groupui-icon-button
            aria-label={this.a11yLabelCloseButton || CLOSE_BUTTON_LABEL}
            class="close-button"
            onClick={this.handleCloseButtonClick}
            variant="inverted"
            icon="close-16"
          ></groupui-icon-button>
        )}
      </Host>
    );
  }
}
